import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { SpaceContext } from '../01_contexts/01_Contexts';
import { useConfig } from '../03_hooks';
import { callApi } from '../api';

export const SpaceProvider = ({ children }) => {
    const { setAppConfig } = useConfig(); 
    
    const [spaces, setSpaces] = useState([]);
    const [isLoading, setIsLoading] = useState(false); // 全域載入
    const [isMutating, setIsMutating] = useState(false); // 操作中載入 (例如匯入、刪除時)
    const [error, setError] = useState(null);

    const refreshData = async (showLoading = true) => {
        console.log("=== 1. 開始呼叫 API ==="); // 確認函式有沒有被執行
        if (showLoading) setIsLoading(true);
        setError(null);
        try {
            const res = await callApi('GET_INITIAL_DATA', []);
            console.log("=== 2. API 回傳內容:", res); // 確認 API 是不是空的

            if (res?.success) {
                console.log("=== 3. 準備更新 State，資料筆數:", res.spaces?.length); // 確認資料量
                setSpaces(res.spaces || []);
                if (res.config) setAppConfig(res.config);
            } else {
                console.warn("=== 警告: API 執行成功但 success 為 false ===");
            }
        } catch (err) {
            console.error("=== 錯誤: 發生攔截的例外:", err);
        } finally {
            setIsLoading(false);
        }
    };

    // 擴充：如果你有其他 API 需要更新 spaces，這裡可以集中管理
    const updateSpaceLocal = useCallback((id, updatedData) => {
        setSpaces(prev => prev.map(s => s.id === id ? { ...s, ...updatedData } : s));
    }, []);

    const value = useMemo(() => ({
        spaces,
        isLoading,
        isMutating,      // 新增：讓 UI 可以區分是「整頁載入」還是「背景更新」
        setIsMutating,   // 新增：讓 ImportModal 可以觸發此狀態
        error,
        refreshData,
        updateSpaceLocal // 新增：提供一個不重刷頁面也能改資料的方法 (Optimistic UI)
    }), [spaces, isLoading, isMutating, error, refreshData, updateSpaceLocal]);

    return (
        <SpaceContext.Provider value={value}>
            {children}
        </SpaceContext.Provider>
    );
};