import { useCallback } from 'react';
import { createUseContext } from './03_globalUseHook';
import { AuthContext } from '../01_contexts/01_Contexts';
import { IS_DEV_MODE } from '../assets/js';

// 1. 先建立基礎 Hook
const useAuthBase = createUseContext(AuthContext, "useAuth");

// 2. 定義你的擴充 Hook
export const useAuth = () => {
    // 取得原始 context 內容
    const context = useAuthBase();
    const { adminToken, setLoginModalOpen, setPendingAction } = context;

    // 3. 封裝權限邏輯
    const withPermission = useCallback((action, intentType) => {
        // 假設 IS_DEV_MODE 是全域變數，記得確保它已定義
        if (typeof IS_DEV_MODE !== 'undefined' && IS_DEV_MODE) return action();

        if (!adminToken) {
            if (intentType) setPendingAction({ type: intentType });
            setLoginModalOpen(true);
            return;
        }

        action();
    }, [adminToken, setLoginModalOpen, setPendingAction]);

    // 4. 回傳擴充後的物件
    return { 
        ...context, 
        withPermission 
    };
};