import { GAS_MAP } from './apiConstants';

export const callApi = async (actionKey, data = {}) => {
  const funcName = GAS_MAP[actionKey];
  const url = `https://script.google.com/macros/s/你的ID/exec?data=${encodeURIComponent(JSON.stringify({ func: funcName, data }))}`;

  try {
    const response = await fetch(url, {
      method: 'GET', // 簡單請求通常不需要預檢
      mode: 'cors'   // 開啟 CORS 模式
    });
    
    if (!response.ok) throw new Error('網路回應失敗');
    return await response.json(); // 直接獲取 JSON 資料
  } catch (error) {
    console.error("Fetch 失敗:", error);
    throw error;
  }
};