import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App'; // 你的主元件
import './assets/App.css';    // 你的樣式

window.handleGasResponse = (data) => {
    // 這裡用一個全域事件來轉發，讓 React 收到
    window.dispatchEvent(new CustomEvent('GAS_DATA_RECEIVED', { detail: data }));
};

ReactDOM.createRoot(document.getElementById('root')).render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);